{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.repeat_order_quant_eoq as with ros_str as ( select sku_group, sum(inventory_on_inward_date*ros)/sum(inventory_on_inward_date) as final_ros from snitch_db.maplemonk.original_ros_str_eoq group by 1 ), lead_time as ( select l1_category, category, actual_lead_time from snitch_db.maplemonk.L1CATEGORY_LEAD_TIME ), category as ( select sku_group, category, case when lower(sku_group) like \'4mbg%\' then \'plus_size\' when lower(style) like \'%luxe%\' then \'luxe\' when lower(style) like \'%core%\' then \'core\' when lower(category) in (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') then \'long_tail\' when lower(style) like \'%revolution%\' then \'revolution\' when lower(style) like \'%bordeaux%\' then \'bordeaux\' else \'Snitch\' end as l1_category from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ), finals as ( select a.*, b.category, b.l1_category from ros_str a left join category b on a.sku_group = b.sku_group ), main_data as ( select a.*,coalesce(b.actual_lead_time,190) as actual_lead_time from finals a left join lead_time b on a.category = b.category and a.l1_category = b.l1_category ), repeat_sku as ( select sku_group, repeat from snitch_db.maplemonk.repeat_decision_eoq ), category_range as ( select distinct category, case when category in (\'Sweaters\',\'Jackets\',\'Sweatshirts\',\'Hoodies\') then \'yes\' else \'no\' end as seasonal, case when category in (\'Sweaters\',\'Jackets\',\'Sweatshirts\') then \'9\' when category in (\'Hoodies\') then \'6\' else null end as min_month, case when category in (\'Sweaters\',\'Jackets\',\'Sweatshirts\') then \'2\' when category in (\'Hoodies\') then \'2\' else null end as max_month from snitch_db.maplemonk.metafields_data where category is not null or category != \'\' ), max_inward_date as ( select a.*, b.repeat, c.seasonal,c.min_month,c.max_month, DATEADD(day, actual_lead_time, current_date) AS inward_date from main_data a left join repeat_sku b on a.sku_group = b.sku_group left join category_range c on a.category = c.category ), days_remaining as ( select *, coalesce((case when try_to_number(min_month) is not null and try_to_number(max_month) is not null then case when inward_date >= dateadd(month, try_to_number(min_month) - 3, date_from_parts(extract(year from current_date), 1, 1)) and inward_date < date_from_parts(extract(year from current_date) + 1, try_to_number(max_month), 1) then 1 else 0 end end),1) as flag, coalesce((case when try_to_number(min_month) is not null and try_to_number(max_month) is not null then case when inward_date > date_from_parts(extract(year from current_date), try_to_number(min_month), 1) then datediff( day, inward_date, dateadd(day, -1, date_from_parts(extract(year from current_date) + 1, try_to_number(max_month) + 1, 1)) ) else datediff( day, date_from_parts(extract(year from current_date), try_to_number(min_month), 1), dateadd(day, -1, date_from_parts(extract(year from current_date) + 1, try_to_number(max_month) + 1, 1)) ) end else null end),actual_lead_time+15) as days_remaining from max_inward_date ), inward_conf as ( select sku_group, inwards_multiplier from snitch_db.maplemonk.inwards_freq_multiplier_eoq ) select a.sku_group, a.final_ros, a.category, a.l1_category, a.actual_lead_time, a.repeat, a.seasonal, a.min_month, a.max_month, a.inward_date, a.flag, case when seasonal = \'yes\' then least(days_remaining,90) else days_remaining end as days_remaining, case when repeat = \'yes\' then (final_ros*case when seasonal = \'yes\' then least(days_remaining,90) else days_remaining end*1.1*flag*b.inwards_multiplier)::int else 0 end as order_quantity from days_remaining a left join inward_conf b on a.sku_group = b.sku_group ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            